patch:
diff --git a/repro/no-loss-of-precision-9000.js b/repro/no-loss-of-precision-9000.js
new file mode 100644
index 0000000..8c3c230
--- /dev/null
+++ b/repro/no-loss-of-precision-9000.js
@@ -0,0 +1,34 @@
+"use strict";
+
+// Reproduction for: no-loss-of-precision flags 9.000e+3 (a value that is exactly 9000).
+// Exits non-zero while any of the literals below is reported, zero once none is.
+// Run from the repo root: node repro/no-loss-of-precision-9000.js
+
+const { Linter } = require("../lib/api");
+
+const linter = new Linter();
+const literals = [
+	"9.000e+3", // reported literal
+	"9.000e3", // from maintainer's comment on the report (marked "error")
+	"9.0000e4", // from maintainer's comment on the report (marked "error")
+];
+
+let failed = false;
+
+for (const literal of literals) {
+	const code = `const test = ${literal}; // ${Number(literal)}`;
+	const messages = linter.verify(code, {
+		rules: { "no-loss-of-precision": "error" },
+	});
+
+	if (messages.length) {
+		failed = true;
+		console.error(
+			`FAIL: ${literal} (value ${Number(literal)}) reported: ${messages.map(m => `${m.ruleId}: ${m.message} (col ${m.column})`).join("; ")}`,
+		);
+	} else {
+		console.log(`ok:   ${literal} not reported`);
+	}
+}
+
+process.exit(failed ? 1 : 0);
